#!/usr/bin/env python3
from pathlib import Path
import sys

root=Path(sys.argv[1] if len(sys.argv)>1 else ".")
app=root/"app.html"
MARK="WAREHOUSE_SUPPLIER_LIVE_V5_20261014"

if not app.exists():
    raise SystemExit("app.html not found")

a=app.read_text(encoding="utf-8")
if MARK in a:
    print("supplier live v5 already applied")
    raise SystemExit(0)

payload = '<script>\n/* WAREHOUSE_SUPPLIER_LIVE_V5_20261014 */\n(function(){\n  if(window.GP_SUPPLIER_LIVE_V5) return;\n  window.GP_SUPPLIER_LIVE_V5=true;\n\n  let timer=0;\n  let fetching=null;\n\n  function txt(v){ return String(v==null?\'\':v).trim(); }\n  function esc2(v){\n    if(typeof esc===\'function\') return esc(v);\n    return txt(v).replace(/[&<>"\']/g,function(ch){return {\'&\':\'&amp;\',\'<\':\'&lt;\',\'>\':\'&gt;\',\'"\':\'&quot;\',"\'":\'&#39;\'}[ch]});\n  }\n\n  async function freshWarehouse(){\n    if(typeof WH!==\'undefined\' && WH && Array.isArray(WH.cartons) && Array.isArray(WH.inventory)) return WH;\n    if(fetching) return fetching;\n    fetching=(async function(){\n      try{\n        if(typeof req!==\'function\') return null;\n        return await req(\'/api/warehouse?gp_supplier_v5=\'+Date.now());\n      }catch(e){ return null; }\n      finally{ fetching=null; }\n    })();\n    return fetching;\n  }\n\n  function mapsFrom(state){\n    const byId=new Map(),byCode=new Map(),bySerial=new Map();\n    const cartons=(state&&state.cartons)||[];\n    const inventory=(state&&state.inventory)||((typeof INV!==\'undefined\'&&Array.isArray(INV))?INV:[]);\n    cartons.forEach(function(c){\n      let supplier=txt(c&&c.supplier);\n      const cid=Number(c&&c.id)||0, code=txt(c&&c.code).toUpperCase();\n      if(supplier){\n        if(cid) byId.set(cid,supplier);\n        if(code) byCode.set(code,supplier);\n      }\n    });\n    inventory.forEach(function(iv){\n      const sn=txt(iv&&iv.serial).toUpperCase();\n      if(!sn) return;\n      let supplier=txt(iv&&iv.supplier);\n      if(!supplier && Number(iv&&iv.carton_id)) supplier=byId.get(Number(iv.carton_id))||\'\';\n      if(!supplier && txt(iv&&iv.carton_code)) supplier=byCode.get(txt(iv.carton_code).toUpperCase())||\'\';\n      if(supplier) bySerial.set(sn,supplier);\n    });\n    return {byId:byId,byCode:byCode,bySerial:bySerial,cartons:cartons,inventory:inventory};\n  }\n\n  function ensureWarehouseHeader(table){\n    const hr=table&&table.querySelector(\'thead tr\');\n    if(!hr) return -1;\n    let th=[].slice.call(hr.children).find(function(x){return x.classList&&x.classList.contains(\'gp-supplier-v5-head\')});\n    if(th) return [].indexOf.call(hr.children,th);\n    const cells=[].slice.call(hr.children);\n    const existing=cells.find(function(x){return /تامین.?کننده/.test(x.textContent||\'\')});\n    if(existing){\n      existing.classList.add(\'gp-supplier-v5-head\');\n      return cells.indexOf(existing);\n    }\n    const modelIndex=cells.findIndex(function(x){return /مدل/.test(x.textContent||\'\')});\n    if(modelIndex<0) return -1;\n    th=document.createElement(\'th\');\n    th.className=\'gp-supplier-v5-head\';\n    th.textContent=\'تامین\u200cکننده\';\n    cells[modelIndex].after(th);\n    return modelIndex+1;\n  }\n\n  function supplierForCarton(c,maps){\n    if(!c) return \'\';\n    let s=txt(c.supplier);\n    if(s) return s;\n    const cid=Number(c.id)||0, code=txt(c.code).toUpperCase();\n    if(cid) s=maps.byId.get(cid)||\'\';\n    if(!s && code) s=maps.byCode.get(code)||\'\';\n    if(!s){\n      const iv=maps.inventory.find(function(x){\n        return (cid && Number(x&&x.carton_id)===cid) || (code && txt(x&&x.carton_code).toUpperCase()===code);\n      });\n      if(iv) s=txt(iv.supplier);\n    }\n    return s;\n  }\n\n  function decorateWarehouse(state){\n    const body=document.getElementById(\'warehouseBody\');\n    if(!body||!state) return;\n    const table=body.closest(\'table\');\n    if(!table) return;\n    const supplierIndex=ensureWarehouseHeader(table);\n    if(supplierIndex<0) return;\n    const maps=mapsFrom(state);\n    const cartons=maps.cartons;\n\n    [].slice.call(body.querySelectorAll(\'tr\')).forEach(function(tr){\n      let cells=[].slice.call(tr.children);\n      if(!cells.length) return;\n      const code=txt(cells[0]&&cells[0].textContent).toUpperCase();\n      if(!code) return;\n      const c=cartons.find(function(x){return txt(x&&x.code).toUpperCase()===code});\n      if(!c) return;\n      const supplier=supplierForCarton(c,maps);\n\n      let cell=tr.querySelector(\'.gp-supplier-v5-cell\');\n      if(!cell){\n        const existing=[].slice.call(tr.children).find(function(td){\n          return td!==cells[1] && td.classList && td.classList.contains(\'gp-supplier-cell\');\n        });\n        if(existing){\n          cell=existing;\n          cell.classList.add(\'gp-supplier-v5-cell\');\n        }else{\n          cell=document.createElement(\'td\');\n          cell.className=\'gp-supplier-v5-cell\';\n          const modelCell=tr.children[1];\n          if(modelCell) modelCell.after(cell);\n          else tr.appendChild(cell);\n        }\n      }\n      cell.innerHTML=supplier?(\'<b>\'+esc2(supplier)+\'</b>\'):\'<span class="small">-</span>\';\n\n      const modelCell=tr.children[1];\n      if(modelCell){\n        [].slice.call(modelCell.querySelectorAll(\'.small\')).forEach(function(x){\n          if(/تامین.?کننده/.test(x.textContent||\'\')) x.remove();\n        });\n      }\n    });\n  }\n\n  function serialFromRow(row){\n    const c=row.querySelector(\'.inv-code\');\n    const t=txt(c?c.textContent:row.textContent);\n    let m=t.match(/SN\\s*:\\s*([A-Z0-9_-]+)/i);\n    if(m) return m[1].toUpperCase();\n    m=t.match(/\\b([A-Z][A-Z0-9_-]{7,})\\b/i);\n    return m?m[1].toUpperCase():\'\';\n  }\n\n  function decorateInventory(state){\n    const root=document.getElementById(\'inventoryGroups\');\n    if(!root||!state) return;\n    const maps=mapsFrom(state);\n    const inv=(typeof INV!==\'undefined\'&&Array.isArray(INV))?INV:maps.inventory;\n    const direct=new Map();\n    inv.forEach(function(iv){\n      const sn=txt(iv&&iv.serial).toUpperCase();\n      if(sn) direct.set(sn,iv);\n    });\n\n    [].slice.call(root.querySelectorAll(\'.inv-serial-row\')).forEach(function(row){\n      const sn=serialFromRow(row);\n      if(!sn) return;\n      const iv=direct.get(sn);\n      let supplier=iv?txt(iv.supplier):\'\';\n      if(!supplier && iv && Number(iv.carton_id)) supplier=maps.byId.get(Number(iv.carton_id))||\'\';\n      if(!supplier && iv && txt(iv.carton_code)) supplier=maps.byCode.get(txt(iv.carton_code).toUpperCase())||\'\';\n      if(!supplier) supplier=maps.bySerial.get(sn)||\'\';\n\n      const product=row.querySelector(\'.inv-product\')||row.firstElementChild;\n      if(!product) return;\n      let badge=product.querySelector(\'.gp-inv-supplier-v5\');\n      if(!badge){\n        badge=document.createElement(\'div\');\n        badge.className=\'gp-inv-supplier-v5\';\n        badge.style.marginTop=\'5px\';\n        product.appendChild(badge);\n      }\n      badge.innerHTML=\'<span class="badge">تامین\u200cکننده: <b>\'+esc2(supplier||\'-\')+\'</b></span>\';\n\n      [].slice.call(product.querySelectorAll(\'.small\')).forEach(function(x){\n        if(/تامین.?کننده/.test(x.textContent||\'\')) x.remove();\n      });\n      const old=product.querySelector(\'.gp-inv-supplier\');\n      if(old && old!==badge) old.remove();\n    });\n  }\n\n  async function refreshSupplierDisplay(forceFetch){\n    let state=null;\n    if(!forceFetch && typeof WH!==\'undefined\' && WH && Array.isArray(WH.cartons)) state=WH;\n    if(!state) state=await freshWarehouse();\n    if(!state) return;\n    decorateWarehouse(state);\n    decorateInventory(state);\n  }\n\n  function schedule(forceFetch){\n    clearTimeout(timer);\n    timer=setTimeout(function(){refreshSupplierDisplay(!!forceFetch);},60);\n  }\n\n  if(typeof loadWarehouse===\'function\' && !loadWarehouse.__gpSupplierV5){\n    const base=loadWarehouse;\n    const wrapped=async function(){\n      const r=await base.apply(this,arguments);\n      schedule(false);\n      return r;\n    };\n    wrapped.__gpSupplierV5=true;\n    loadWarehouse=wrapped;\n  }\n\n  if(typeof renderWarehouse===\'function\' && !renderWarehouse.__gpSupplierV5){\n    const base=renderWarehouse;\n    const wrapped=function(){\n      const r=base.apply(this,arguments);\n      schedule(false);\n      return r;\n    };\n    wrapped.__gpSupplierV5=true;\n    renderWarehouse=wrapped;\n  }\n\n  if(typeof loadInventory===\'function\' && !loadInventory.__gpSupplierV5){\n    const base=loadInventory;\n    const wrapped=async function(){\n      const r=await base.apply(this,arguments);\n      schedule(true);\n      return r;\n    };\n    wrapped.__gpSupplierV5=true;\n    loadInventory=wrapped;\n  }\n\n  if(typeof renderInventory===\'function\' && !renderInventory.__gpSupplierV5){\n    const base=renderInventory;\n    const wrapped=function(){\n      const r=base.apply(this,arguments);\n      schedule(false);\n      return r;\n    };\n    wrapped.__gpSupplierV5=true;\n    renderInventory=wrapped;\n  }\n\n  new MutationObserver(function(){ schedule(false); }).observe(document.body,{childList:true,subtree:true});\n  setTimeout(function(){schedule(true);},300);\n  setTimeout(function(){schedule(true);},1200);\n})();\n</script>\n'
pos=a.lower().rfind("</body>")
if pos<0:
    raise SystemExit("</body> not found")
a=a[:pos]+payload+a[pos:]
app.write_text(a,encoding="utf-8")
print("supplier live v5 patch applied")
